import{_ as i,o as a,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"教程：素材系统与组件挂载解析","description":"","frontmatter":{},"headers":[],"relativePath":"教程资料/专题研究/素材系统与组件挂载解析.md","filePath":"教程资料/专题研究/素材系统与组件挂载解析.md","lastUpdated":1777893104000}'),h={name:"教程资料/专题研究/素材系统与组件挂载解析.md"};function d(n,l,o,t,c,p){return a(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="教程-素材系统与组件挂载解析" tabindex="-1">教程：素材系统与组件挂载解析 <a class="header-anchor" href="#教程-素材系统与组件挂载解析" aria-label="Permalink to “教程：素材系统与组件挂载解析”">​</a></h1><ul><li>分类：教程专题</li><li>子系统：素材 / 物体 / 组件挂载 / 素材库管理 / 贴图文件夹</li><li>关键词标签：素材, 物体, 组件挂载, 导入素材, 复制素材, 移动素材, 贴图文件夹</li><li>来源类型：官方教程截图主题整理</li><li>证据等级：截图直接证据 + 主题归纳</li><li>完整度状态：深度整理</li><li>来源文件：<code>资料/官方教程文档截图/</code></li><li>对应 OCR 文档：<code>docs/OCR资料/官方教程截图转文本索引.md</code></li><li>来源截图编号：105946, 110035</li><li>对应映射表：<code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li>最后更新：2026-04-20</li></ul><p>本文件基于 <code>资料/官方教程文档截图/</code> 中关于“素材的基础操作”“什么是素材”“移动素材”“给素材添加组件”等内容整理，目标是把素材系统单独沉淀成一篇更完整的专题文档。</p><h2 id="_1-素材是什么" tabindex="-1">1. 素材是什么 <a class="header-anchor" href="#_1-素材是什么" aria-label="Permalink to “1. 素材是什么”">​</a></h2><p>根据教程截图可确认：</p><ul><li>素材不是单纯图片</li><li>素材是【贴图】和【各种组件】的组合体</li><li>素材放到地图中后，才会成为物体（object）</li></ul><h3 id="这意味着什么" tabindex="-1">这意味着什么 <a class="header-anchor" href="#这意味着什么" aria-label="Permalink to “这意味着什么”">​</a></h3><p>创游中的“素材”更像一个模板：</p><ul><li>它定义外观</li><li>它定义可挂载的功能组件</li><li>它是放入地图前的设计单位</li></ul><p>而“物体”则更像该模板在地图中的实例。</p><h2 id="_2-素材与物体的区别" tabindex="-1">2. 素材与物体的区别 <a class="header-anchor" href="#_2-素材与物体的区别" aria-label="Permalink to “2. 素材与物体的区别”">​</a></h2><p>教程明确指出：</p><ul><li>素材 ≠ 物体</li><li>将素材摆到地图中后，才成为物体</li></ul><h3 id="理解方式" tabindex="-1">理解方式 <a class="header-anchor" href="#理解方式" aria-label="Permalink to “理解方式”">​</a></h3><p>可以把它类比成：</p><ul><li>素材 = 预制件 / 模板</li><li>物体 = 实际放到关卡中的实例</li></ul><h3 id="这个区别为什么重要" tabindex="-1">这个区别为什么重要 <a class="header-anchor" href="#这个区别为什么重要" aria-label="Permalink to “这个区别为什么重要”">​</a></h3><p>因为很多初学者会混淆：</p><ul><li>在素材阶段能改的是模板定义</li><li>在地图里操作的是实例状态与摆放结果</li></ul><p>这也解释了为什么教程会单独讲“素材库”“导入素材”“复制素材”“给素材添加组件”。</p><h2 id="_3-素材分类" tabindex="-1">3. 素材分类 <a class="header-anchor" href="#_3-素材分类" aria-label="Permalink to “3. 素材分类”">​</a></h2><p>根据教程截图，地图素材至少分为六类：</p><ul><li>地块</li><li>装饰</li><li>角色</li><li>装置</li><li>道具</li><li>武器</li></ul><p>另外还有：</p><ul><li>UI 素材</li></ul><h3 id="结构理解" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解" aria-label="Permalink to “结构理解”">​</a></h3><p>这说明素材系统是创游世界编辑器的基础组织结构之一。不同大类决定：</p><ul><li>默认用途</li><li>可挂载组件范围</li><li>在地图中的交互角色</li></ul><h2 id="_4-素材的导入与管理" tabindex="-1">4. 素材的导入与管理 <a class="header-anchor" href="#_4-素材的导入与管理" aria-label="Permalink to “4. 素材的导入与管理”">​</a></h2><p>根据“素材的基础操作”与“移动素材”相关截图，可确认：</p><ul><li>每个大类素材栏最左边的蓝色 <code>+</code> 是导入素材入口</li><li>导入素材至少有多种方式</li><li>当素材逐渐增多时，可以创建文件夹进行整理</li><li>可以通过齿轮菜单中的“移动至”来移动素材</li><li>也可以长按拖拽素材，直接拖入文件夹</li></ul><h3 id="这说明什么" tabindex="-1">这说明什么 <a class="header-anchor" href="#这说明什么" aria-label="Permalink to “这说明什么”">​</a></h3><p>创游素材库不是一次性塞满的，而是鼓励创作者：</p><ul><li>分类型管理</li><li>用文件夹整理</li><li>保持素材库可维护性</li></ul><h2 id="_5-复制素材" tabindex="-1">5. 复制素材 <a class="header-anchor" href="#_5-复制素材" aria-label="Permalink to “5. 复制素材”">​</a></h2><p>OCR 内容表明：</p><ul><li>可以复制素材，生成当前素材的一份副本</li><li>复制素材时，有时可以改变当前素材类型</li><li>但地块复制时不可以改变素材类型</li></ul><h3 id="结构理解-1" tabindex="-1">结构理解 <a class="header-anchor" href="#结构理解-1" aria-label="Permalink to “结构理解”">​</a></h3><p>这说明复制系统可能支持“近似模板迁移”，但并非所有类型都完全开放。</p><h3 id="对创作者的意义" tabindex="-1">对创作者的意义 <a class="header-anchor" href="#对创作者的意义" aria-label="Permalink to “对创作者的意义”">​</a></h3><p>复制素材很适合：</p><ul><li>快速做变体</li><li>基于已有素材迭代</li><li>在保留大部分配置的前提下微调功能</li></ul><h2 id="_6-素材的贴图文件夹" tabindex="-1">6. 素材的贴图文件夹 <a class="header-anchor" href="#_6-素材的贴图文件夹" aria-label="Permalink to “6. 素材的贴图文件夹”">​</a></h2><p>OCR 内容指出：</p><ul><li>当一个素材有多张贴图，或者有动画时</li><li>素材在素材库内会变成一个文件夹</li></ul><h3 id="这说明什么-1" tabindex="-1">这说明什么 <a class="header-anchor" href="#这说明什么-1" aria-label="Permalink to “这说明什么”">​</a></h3><p>贴图资源并不总是单帧静态图。 创游素材系统能够承载：</p><ul><li>多贴图资源</li><li>动画资源</li><li>更复杂的表现集合</li></ul><p>这与显示类组件、动画脚本块、粒子特效等内容是互相呼应的。</p><h2 id="_7-给素材添加组件" tabindex="-1">7. 给素材添加组件 <a class="header-anchor" href="#_7-给素材添加组件" aria-label="Permalink to “7. 给素材添加组件”">​</a></h2><p>教程截图明确指出：</p><ul><li>给素材添加组件，可以赋予素材功能</li><li>但不同类型的素材，能添加的组件不同</li></ul><h3 id="这意味着什么-1" tabindex="-1">这意味着什么 <a class="header-anchor" href="#这意味着什么-1" aria-label="Permalink to “这意味着什么”">​</a></h3><p>组件是“功能挂载层”，素材是“承载模板层”。</p><p>也就是说，素材本身不是功能全开的，它需要通过组件来获得能力。例如：</p><ul><li>地块通过地块组件获得阻挡、摩擦等能力</li><li>道具通过道具组件获得使用逻辑</li><li>子弹通过子弹组件获得推进、反弹、穿透能力</li></ul><h3 id="这也解释了教程结构" tabindex="-1">这也解释了教程结构 <a class="header-anchor" href="#这也解释了教程结构" aria-label="Permalink to “这也解释了教程结构”">​</a></h3><p>为什么官方会分别讲：</p><ul><li>什么是素材</li><li>素材的基础操作</li><li>什么是自定义组件</li><li>地块组件</li><li>道具组件</li><li>子弹组件</li></ul><p>因为这些其实都是同一套“模板 + 组件”体系的不同侧面。</p><h2 id="_8-素材系统对知识库的价值" tabindex="-1">8. 素材系统对知识库的价值 <a class="header-anchor" href="#_8-素材系统对知识库的价值" aria-label="Permalink to “8. 素材系统对知识库的价值”">​</a></h2><p>把素材系统单独整理出来很重要，因为它是连接多个主题的中轴：</p><ul><li>它连接组件系统</li><li>它连接对象实例化</li><li>它连接地图编辑</li><li>它连接贴图与动画资源管理</li></ul><p>未来如果做 AI 问答或 RAG 检索，很多问题都可以归到这个专题下，例如：</p><ul><li>素材和物体有什么区别？</li><li>为什么某个组件挂不上？</li><li>怎么整理素材库？</li><li>能不能复制后改类型？</li><li>多贴图素材在素材库里为什么像文件夹？</li></ul><h2 id="_9-关键词" tabindex="-1">9. 关键词 <a class="header-anchor" href="#_9-关键词" aria-label="Permalink to “9. 关键词”">​</a></h2><ul><li>素材</li><li>物体</li><li>object</li><li>贴图</li><li>组件</li><li>导入素材</li><li>创建文件夹</li><li>移动素材</li><li>复制素材</li><li>素材类型</li><li>地块</li><li>角色</li><li>装置</li><li>道具</li><li>武器</li><li>UI素材</li></ul>',67)])])}const u=i(h,[["render",d]]);export{_ as __pageData,u as default};
